import { useEffect, useRef, useState } from "react";

export interface CountdownProps {
  /** Total seconds to count down from. */
  seconds: number;
  /** Called exactly once when the countdown reaches zero. */
  onExpire?: () => void;
}

export function formatClock(totalSeconds: number): string {
  const clamped = Math.max(0, totalSeconds);
  const minutes = Math.floor(clamped / 60);
  const secs = clamped % 60;
  return `${String(minutes).padStart(2, "0")}:${String(secs).padStart(2, "0")}`;
}

export function Countdown({ seconds, onExpire }: CountdownProps) {
  const [remaining, setRemaining] = useState(seconds);
  const [paused, setPaused] = useState(false);

  // Stale-closure guard: the interval is created once with [] deps, so its
  // callback would otherwise capture the *initial* `paused` forever. The
  // callback therefore reads the mutable ref instead of the captured state.
  const pausedRef = useRef(false);
  useEffect(() => {
    pausedRef.current = paused;
  }, [paused]);

  // Fires onExpire exactly once, even if the effect re-runs or the interval
  // keeps ticking past zero.
  const expiredRef = useRef(false);
  useEffect(() => {
    if (remaining === 0 && !expiredRef.current) {
      expiredRef.current = true;
      onExpire?.();
    }
  }, [remaining, onExpire]);

  useEffect(() => {
    const id = setInterval(() => {
      if (!pausedRef.current && !expiredRef.current) {
        setRemaining((prev) => Math.max(0, prev - 1));
      }
    }, 1000);
    return () => clearInterval(id);
  }, []);

  return (
    <div>
      <time data-testid="clock">{formatClock(remaining)}</time>
      <div>
        <button
          type="button"
          onClick={() => setPaused(true)}
          disabled={paused || remaining === 0}
        >
          Pause
        </button>
        <button
          type="button"
          onClick={() => setPaused(false)}
          disabled={!paused}
        >
          Resume
        </button>
      </div>
      {remaining === 0 ? <span>Expired</span> : null}
    </div>
  );
}

