import { act, cleanup, fireEvent, render, screen } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { Countdown } from "./Countdown";

beforeEach(() => {
  vi.useFakeTimers();
});

afterEach(() => {
  cleanup();
  vi.useRealTimers();
});

const clock = () => screen.getByTestId("clock");

describe("Countdown", () => {
  it("renders the initial value as mm:ss", () => {
    render(<Countdown seconds={95} />);
    expect(clock().textContent).toBe("01:35");
    expect(screen.queryByText("Expired")).toBeNull();
  });

  it("ticks down and asserts rendered strings at several points", () => {
    render(<Countdown seconds={65} />);

    expect(clock().textContent).toBe("01:05"); // t = 0s

    act(() => {
      vi.advanceTimersByTime(1000);
    });
    expect(clock().textContent).toBe("01:04"); // t = 1s

    act(() => {
      vi.advanceTimersByTime(2000);
    });
    expect(clock().textContent).toBe("01:02"); // t = 3s

    act(() => {
      vi.advanceTimersByTime(4000);
    });
    expect(clock().textContent).toBe("00:58"); // t = 7s
  });

  // Covers the stale-closure bug: pause is clicked immediately after a tick
  // boundary. The interval callback (created once at mount) must observe this
  // *latest* paused state, not whatever `paused` was when the interval was set.
  it("pausing right after a tick boundary freezes the display while timers advance", () => {
    render(<Countdown seconds={10} />);
    expect(clock().textContent).toBe("00:10");

    act(() => {
      vi.advanceTimersByTime(1000); // tick boundary crossed -> 00:09
    });
    expect(clock().textContent).toBe("00:09");

    fireEvent.click(screen.getByRole("button", { name: "Pause" }));

    // Plenty of ticks fire while paused; every one must see pausedRef=true.
    act(() => {
      vi.advanceTimersByTime(7000);
    });
    expect(clock().textContent).toBe("00:09");
  });

  it("resumes from the frozen value after a long pause", () => {
    render(<Countdown seconds={5} />);

    act(() => {
      vi.advanceTimersByTime(2000);
    });
    expect(clock().textContent).toBe("00:03");

    fireEvent.click(screen.getByRole("button", { name: "Pause" }));
    act(() => {
      vi.advanceTimersByTime(10000); // frozen at 00:03
    });

    fireEvent.click(screen.getByRole("button", { name: "Resume" }));
    act(() => {
      vi.advanceTimersByTime(1000);
    });
    expect(clock().textContent).toBe("00:02");

    act(() => {
      vi.advanceTimersByTime(1000);
    });
    expect(clock().textContent).toBe("00:01");
  });

  it("fires onExpire exactly once and shows Expired, even with extra time passing", () => {
    const onExpire = vi.fn();
    render(<Countdown seconds={3} onExpire={onExpire} />);

    act(() => {
      vi.advanceTimersByTime(1000);
    });
    expect(onExpire).not.toHaveBeenCalled();
    expect(screen.queryByText("Expired")).toBeNull();

    act(() => {
      vi.advanceTimersByTime(1000);
    });
    expect(onExpire).toHaveBeenCalledTimes(0);

    act(() => {
      vi.advanceTimersByTime(1000); // reaches zero
    });
    expect(clock().textContent).toBe("00:00");
    expect(onExpire).toHaveBeenCalledTimes(1);
    expect(screen.getByText("Expired")).toBeTruthy();

    // Keep time flowing well past expiry — still exactly one call.
    act(() => {
      vi.advanceTimersByTime(30000);
    });
    expect(onExpire).toHaveBeenCalledTimes(1);
    expect(clock().textContent).toBe("00:00");
    expect(screen.getByText("Expired")).toBeTruthy();
  });
});

